<template>
  <div class="ui-case-page">
    <header class="page-header"><div><div class="breadcrumb">UI 自动化 / Playwright 智能用例 / {{ id ? '编辑用例' : '新增用例' }}</div><div class="title-line"><h1>{{ id ? '编辑智能 UI 用例' : '新增智能 UI 用例' }}</h1><p>页面元素默认使用语义描述，勾选手动兜底后可填写表达式</p></div></div><n-space><n-button size="large" @click="back">取消</n-button><n-button type="primary" size="large" :loading="saving" @click="save">保存用例</n-button></n-space></header>
    <n-form ref="formRef" :model="form" label-placement="top"><section class="basic-section"><h2>基本信息</h2><div class="basic-grid"><n-form-item label="用例名称"><n-input v-model:value="form.name" /></n-form-item><n-form-item label="所属项目"><n-select v-model:value="form.project" :options="projects" filterable /></n-form-item><n-form-item label="执行环境"><n-input v-model:value="form.environment_name" placeholder="如 Dev" /></n-form-item><n-form-item label="浏览器"><n-select v-model:value="form.browser" :options="browserOptions" /></n-form-item><n-form-item label="运行模式"><n-select v-model:value="form.run_mode" :options="modeOptions" /></n-form-item><n-form-item label="默认超时（毫秒）"><n-input-number v-model:value="form.default_timeout" :min="100" :max="300000" /></n-form-item><n-form-item label="用例描述" class="description"><n-input v-model:value="form.description" maxlength="250" show-count /></n-form-item><n-form-item label="启用"><n-switch v-model:value="form.enabled" /></n-form-item></div></section></n-form>
    <section class="steps-section"><div class="section-heading"><h2>操作步骤</h2><p>填写用户可见的页面元素描述；引擎会按标签、角色、属性和历史指纹评分定位</p><n-button type="primary" secondary @click="addStep">＋ 添加步骤</n-button></div><div class="step-table-wrap"><div class="step-table-head"><span>顺序</span><span>步骤名称</span><span>操作方式</span><span>页面元素 / 访问地址</span><span>操作值</span><span>操作</span></div><draggable v-model="steps" item-key="localKey" handle=".drag-handle" class="step-list" ghost-class="step-ghost"><template #item="{ element: step, index }"><div class="step-entry" :class="{ expanded: step.expanded }"><div class="step-row"><div class="order-cell"><button class="drag-handle">⠿</button><button class="expand-button" :class="{ open: step.expanded }" @click="step.expanded = !step.expanded">›</button><strong>{{ String(index + 1).padStart(2, '0') }}</strong></div><n-input :value="step.name" placeholder="步骤名称（自动生成，可手动修改）" @update:value="(value) => updateStepName(step, value)"/><n-select :value="step.action" :options="actionOptions" @update:value="(value) => updateAction(step, value)"/><n-input :value="step.target" :placeholder="targetPlaceholder(step.action)" @update:value="(value) => updateTarget(step, value)"/><n-input v-if="needsValue(step.action)" :value="step.value" :type="isSensitive(step) ? 'password' : 'text'" :placeholder="valuePlaceholder(step.action)" show-password-on="click" @update:value="(value) => updateValue(step, value)"/><span v-else class="empty-cell">——</span><n-button text type="error" @click="removeStep(index)">删除</n-button></div><div v-if="step.expanded" class="advanced-row"><template v-if="!step.manual_fallback"><n-input v-model:value="step.smartAliases" placeholder="智能别名（可选，逗号分隔）" class="alias-input" @update:value="syncAliases(step)"/><n-select v-model:value="step.smartRole" :options="roleOptions" clearable placeholder="限定角色（可选）" class="role-select" @update:value="syncRole(step)"/><n-input-number v-model:value="step.options.timeout" :min="1" :max="300" class="timeout-input"/><span class="timeout-label">步骤超时（秒）</span></template><n-checkbox v-model:checked="step.manual_fallback">手动兜底</n-checkbox><template v-if="step.manual_fallback"><n-select v-model:value="step.fallback_type" :options="fallbackTypes" class="fallback-type"/><n-input v-model:value="step.fallback_value" placeholder="表达式，如 input[name='account']" class="fallback-input"/></template><n-checkbox v-model:checked="step.continue_on_failure">失败后继续</n-checkbox></div></div></template></draggable><n-empty v-if="!steps.length" description="请添加操作步骤" class="step-empty"/><button class="add-step" @click="addStep">＋ 添加操作步骤</button></div><div class="execution-rule">执行规则：仅当候选元素唯一且置信度足够时自动操作；有歧义时请补充描述、别名、角色或手动兜底表达式。</div></section>
    <footer class="sticky-actions"><n-button size="large" @click="back">取消</n-button><n-button type="primary" size="large" :loading="saving" @click="save">保存用例</n-button></footer>
  </div>
</template>
<script lang="ts" setup>
import { onMounted, reactive, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { useMessage } from 'naive-ui'; import draggable from 'vuedraggable'; import { PlaywrightCaseAPI } from '@/api/case_ui/http'; import { ProjectAPI } from '@/api/project/http';
const route=useRoute(); const router=useRouter(); const message=useMessage(); const id=Number(route.params.id); const api=new PlaywrightCaseAPI(); const projectApi=new ProjectAPI(); const formRef=ref<any>(); const saving=ref(false); const projects=ref<any[]>([]); const steps=ref<any[]>([]);
const form=reactive<any>({name:'',project:null,description:'',browser:'chromium',run_mode:'headless',environment_name:'',default_timeout:10000,viewport:{width:1440,height:900},enabled:true}); const browserOptions=[{label:'Chromium',value:'chromium'},{label:'Firefox',value:'firefox'},{label:'WebKit',value:'webkit'}]; const modeOptions=[{label:'无头模式',value:'headless'},{label:'有界面模式',value:'headed'}]; const actionOptions=[['goto','打开页面'],['input','输入文本'],['click','点击'],['select','选择下拉项'],['check','勾选'],['assert_visible','断言可见'],['assert_text','断言文本'],['save_text','提取文本'],['sleep','固定等待']].map(([value,label])=>({value,label})); const actionLabels=Object.fromEntries(actionOptions.map(item=>[item.value,item.label])); const fallbackTypes=[{label:'ID',value:'id'},{label:'Name',value:'name'},{label:'Class Name',value:'class_name'},{label:'Link Text',value:'link_text'},{label:'CSS',value:'css_selector'},{label:'XPath',value:'xpath'}]; const normalizeFallbackType=(value:string)=>({css:'css_selector',testid:'css_selector',test_id:'css_selector'} as Record<string,string>)[value]||value||'xpath'; const roleOptions=['textbox','button','link','combobox','checkbox','radio','tab','menuitem'].map(value=>({label:value,value}));
const needsValue=(a:string)=>['input','select','assert_text','save_text','sleep'].includes(a); const targetPlaceholder=(a:string)=>a==='goto'?'访问地址，如 /login 或 https://...':a==='sleep'?'该操作无需页面元素':'页面元素描述，如 登录账号、订单编号'; const valuePlaceholder=(a:string)=>a==='input'?'输入内容，支持 ${变量名}':a==='save_text'?'保存变量名':a==='sleep'?'等待秒数':'操作值'; const isSensitive=(s:any)=>/密码|password|token|secret/i.test(`${s.name} ${s.target}`); const autoName=(s:any)=>{const action=actionLabels[s.action]||s.action||'操作';const subject=s.action==='sleep'?(s.value?`${s.value}秒`: ''):(s.target||'');return subject?`${action}：${subject}`:action}; const refreshAutoName=(s:any)=>{if(s.nameAuto||!String(s.name||'').trim()){s.name=autoName(s);s.nameAuto=true}}; const updateStepName=(s:any,value:string)=>{s.name=value;s.nameAuto=!String(value||'').trim()||value===autoName(s);if(!String(value||'').trim())refreshAutoName(s)}; const updateAction=(s:any,value:string)=>{s.action=value;refreshAutoName(s)}; const updateTarget=(s:any,value:string)=>{s.target=value;refreshAutoName(s)}; const updateValue=(s:any,value:string)=>{s.value=value;if(s.action==='sleep')refreshAutoName(s)}; const ensureSmart=(s:any)=>{s.options=s.options||{};s.options.smart_locator=s.options.smart_locator||{};return s.options.smart_locator}; const syncAliases=(s:any)=>{const smart=ensureSmart(s);smart.aliases=String(s.smartAliases||'').split(',').map((v:string)=>v.trim()).filter(Boolean)}; const syncRole=(s:any)=>{const smart=ensureSmart(s);if(s.smartRole)smart.role=s.smartRole;else delete smart.role}; const addStep=()=>{const step:any={localKey:`${Date.now()}-${Math.random()}`,name:'',nameAuto:true,action:'click',target:'',value:'',manual_fallback:false,fallback_type:'xpath',fallback_value:'',smartAliases:'',smartRole:'',options:{timeout:10,smart_locator:{}},continue_on_failure:false};refreshAutoName(step);steps.value.push(step)}; const removeStep=(i:number)=>steps.value.splice(i,1); const back=()=>router.push({name:'case_ui_playwright_case'}); const asList=(p:any)=>Array.isArray(p)?p:p?.list||p?.results||p?.data||[];
async function load(){projects.value=asList(await projectApi.getDataList({pageSize:1000})).map((p:any)=>({label:p.name,value:p.id}));if(!id)return;const data:any=await api.getDataByID(id);Object.assign(form,data);const response:any=await api.getDataList({case:id,pageSize:1000});steps.value=asList(response).map((s:any)=>{const options={...(s.options||{})};const timeout=Number(options.timeout??10);options.timeout=timeout>300?Math.round(timeout/1000):timeout;const smart=options.smart_locator||{};const step:any={...s,fallback_type:normalizeFallbackType(s.fallback_type),localKey:`saved-${s.id}`,expanded:false,manual_fallback:s.locator_mode==='manual',smartAliases:Array.isArray(smart.aliases)?smart.aliases.join(', '):'',smartRole:smart.role||'',options};step.nameAuto=step.name===autoName(step);return step});}
async function save(){try{await formRef.value?.validate();if(!form.name||!form.project)throw new Error('请填写用例名称并选择项目');if(!steps.value.length)throw new Error('请至少添加一个步骤');for(const [i,s] of steps.value.entries()){if(!s.name||(!s.target&&s.action!=='sleep'))throw new Error(`第 ${i+1} 步请填写名称和页面元素`);syncAliases(s);syncRole(s);if(s.manual_fallback&&!s.fallback_value)throw new Error(`第 ${i+1} 步请填写手动兜底表达式`);}saving.value=true;const saved:any=id?await api.update(id,{...form}):await api.createData({...form});await api.syncSteps(saved.id,steps.value.map((source:any,index:number)=>{const{localKey,expanded,manual_fallback,smartAliases,smartRole,nameAuto,action_name,...step}=source;return {...step,case:saved.id,order:index+1,locator_mode:manual_fallback?'manual':'auto',fallback_value:manual_fallback?step.fallback_value:''};}));message.success('保存成功');back();}catch(error:any){message.error(error?.message||'保存失败');}finally{saving.value=false;}}
onMounted(load);
</script>
<style scoped lang="less">.ui-case-page{min-height:100%;padding:20px 28px 92px;color:#1d2738;background:#f7f9fc}.page-header{display:flex;align-items:flex-end;justify-content:space-between;max-width:1540px;margin:0 auto 16px}.breadcrumb{color:#748197;font-size:13px}.title-line{display:flex;gap:20px;align-items:baseline;margin-top:12px}.title-line h1{margin:0;font-size:26px}.title-line p{margin:0;color:#718096}.basic-section,.steps-section{max-width:1540px;margin:0 auto 14px;padding:18px 20px 20px;border:1px solid #dfe5ed;border-radius:9px;background:#fff}.basic-section h2,.steps-section h2{margin:0;font-size:18px}.basic-grid{display:grid;grid-template-columns:1.2fr 1fr .9fr .9fr .9fr .95fr;gap:16px 24px;margin-top:16px}.description{grid-column:span 4}.section-heading{display:flex;gap:18px;align-items:center;margin-bottom:14px}.section-heading p{flex:1;margin:0;color:#7b8798;font-size:13px}.step-table-wrap{overflow:hidden;border:1px solid #dfe5ed;border-radius:7px}.step-table-head,.step-row{display:grid;grid-template-columns:118px minmax(140px,1fr) 145px minmax(190px,1.2fr) minmax(170px,1.1fr) 64px;gap:10px;align-items:center}.step-table-head{min-height:46px;padding:0 14px;color:#5e6b7e;background:#fafbfd;border-bottom:1px solid #dfe5ed}.step-row{min-height:62px;padding:7px 14px;border-bottom:1px solid #e7ebf1}.step-entry.expanded{box-shadow:inset 0 0 0 1px #76a8f5}.order-cell{display:flex;gap:8px;align-items:center}.drag-handle,.expand-button{width:25px;height:30px;border:0;color:#8b99ab;background:transparent;cursor:pointer}.expand-button{font-size:22px}.expand-button.open{transform:rotate(90deg)}.empty-cell{text-align:center;color:#a3adba}.advanced-row{display:flex;flex-wrap:wrap;gap:12px;align-items:center;padding:12px 18px 12px 72px;border-bottom:1px solid #e7ebf1;background:#f8fbff}.alias-input{width:260px}.role-select{width:160px}.timeout-input{width:106px}.timeout-label{color:#69778c;font-size:13px}.fallback-type{width:110px}.fallback-input{min-width:280px;flex:1}.add-step{width:calc(100% - 20px);height:44px;margin:10px;border:1px dashed #86b4fb;border-radius:6px;color:#1769e8;background:#fff;cursor:pointer}.execution-rule{margin-top:14px;padding:13px;border:1px solid #d8e8ff;border-radius:7px;color:#3672c8;background:#eff6ff}.sticky-actions{position:fixed;z-index:20;right:0;bottom:0;left:0;display:flex;gap:12px;justify-content:flex-end;padding:12px 34px;border-top:1px solid #dfe5ed;background:#fff}.step-ghost{border:1px dashed #2475ef;background:#edf5ff}@media(max-width:1200px){.basic-grid{grid-template-columns:repeat(3,1fr)}.description{grid-column:span 2}}@media(max-width:760px){.ui-case-page{padding:14px}.page-header,.title-line{align-items:flex-start;flex-direction:column}.basic-grid{grid-template-columns:1fr}.description{grid-column:auto}.steps-section{overflow-x:auto}.step-table-wrap{min-width:900px}}</style>
